import re


def compare(a: str, b: str) -> int:
    """Compare two semantic versions according to SemVer 2.0.0 rules.

    Returns -1 if a < b, 0 if equal precedence, 1 if a > b.
    Raises ValueError for invalid version strings.
    """
    ver_a = _parse_version(a)
    ver_b = _parse_version(b)

    # Compare MAJOR.MINOR.PATCH numerically
    if ver_a['major'] != ver_b['major']:
        return -1 if ver_a['major'] < ver_b['major'] else 1
    if ver_a['minor'] != ver_b['minor']:
        return -1 if ver_a['minor'] < ver_b['minor'] else 1
    if ver_a['patch'] != ver_b['patch']:
        return -1 if ver_a['patch'] < ver_b['patch'] else 1

    # Compare prerelease versions
    return _compare_prerelease(ver_a['prerelease'], ver_b['prerelease'])


def _parse_version(version_str: str) -> dict:
    """Parse and validate a semantic version string."""
    if version_str.startswith('v') or version_str.startswith('V'):
        raise ValueError("v prefix not allowed")

    if any(c.isspace() for c in version_str):
        raise ValueError("whitespace not allowed")

    # Split BUILD metadata (ignored for precedence but must be valid)
    if '+' in version_str:
        version_part, build_part = version_str.rsplit('+', 1)
        _validate_build(build_part)
    else:
        version_part = version_str

    # Split PRERELEASE
    if '-' in version_part:
        core_part, prerelease_str = version_part.split('-', 1)
        prerelease = _parse_prerelease(prerelease_str)
    else:
        core_part = version_part
        prerelease = None

    # Parse MAJOR.MINOR.PATCH
    parts = core_part.split('.')
    if len(parts) != 3:
        raise ValueError("must have MAJOR.MINOR.PATCH")

    try:
        major = _parse_numeric_field(parts[0])
        minor = _parse_numeric_field(parts[1])
        patch = _parse_numeric_field(parts[2])
    except ValueError:
        raise ValueError("invalid numeric field")

    return {
        'major': major,
        'minor': minor,
        'patch': patch,
        'prerelease': prerelease
    }


def _parse_numeric_field(s: str) -> int:
    """Parse MAJOR/MINOR/PATCH field (no leading zeros except '0')."""
    if not s or not s.isdigit():
        raise ValueError("not numeric")
    if len(s) > 1 and s[0] == '0':
        raise ValueError("leading zero")
    return int(s)


def _parse_prerelease(prerelease_str: str) -> list:
    """Parse and validate prerelease identifiers."""
    if not prerelease_str:
        raise ValueError("empty prerelease")

    identifiers = prerelease_str.split('.')
    parsed = []

    for identifier in identifiers:
        if not identifier:
            raise ValueError("empty identifier")

        if identifier.isdigit():
            # Numeric identifier: digits only, no leading zeros except '0'
            if len(identifier) > 1 and identifier[0] == '0':
                raise ValueError("leading zero in numeric identifier")
            parsed.append(('numeric', int(identifier)))
        else:
            # Alphanumeric identifier: must contain at least one non-digit
            if not re.match(r'^[a-zA-Z0-9-]+$', identifier):
                raise ValueError("invalid characters in identifier")
            parsed.append(('alphanumeric', identifier))

    return parsed


def _validate_build(build_str: str) -> None:
    """Validate build metadata (ignored for precedence)."""
    if not build_str:
        raise ValueError("empty build")

    identifiers = build_str.split('.')
    for identifier in identifiers:
        if not identifier:
            raise ValueError("empty build identifier")
        if not re.match(r'^[a-zA-Z0-9-]+$', identifier):
            raise ValueError("invalid build metadata")


def _compare_prerelease(pre_a, pre_b) -> int:
    """Compare two prerelease versions.

    Rules:
    - Version without prerelease has higher precedence than with prerelease.
    - Numeric identifiers compare numerically.
    - Alphanumeric identifiers compare as ASCII strings.
    - Numeric identifiers have lower precedence than alphanumeric.
    - Shorter prerelease list has lower precedence if all common identifiers equal.
    """
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1  # a > b (no prerelease > prerelease)
    if pre_b is None:
        return -1  # a < b (prerelease < no prerelease)

    # Both have prerelease: compare identifier by identifier
    for i in range(min(len(pre_a), len(pre_b))):
        type_a, val_a = pre_a[i]
        type_b, val_b = pre_b[i]

        if type_a == 'numeric' and type_b == 'numeric':
            # Both numeric: compare numerically
            if val_a != val_b:
                return -1 if val_a < val_b else 1
        elif type_a == 'numeric':
            # Numeric < alphanumeric
            return -1
        elif type_b == 'numeric':
            # Alphanumeric > numeric
            return 1
        else:
            # Both alphanumeric: compare as ASCII strings
            if val_a != val_b:
                return -1 if val_a < val_b else 1

    # All compared identifiers equal: shorter list has lower precedence
    if len(pre_a) < len(pre_b):
        return -1
    elif len(pre_a) > len(pre_b):
        return 1
    return 0

haiku-low.stack_vm:
class VMError(Exception):
    pass


class StackUnderflow(VMError):
    pass


class BadJump(VMError):
    pass


class BadOpcode(VMError):
    pass


class StepLimitExceeded(VMError):
    pass


class VMZeroDivision(VMError):
    pass


def run(program: list[tuple], max_steps: int = 10_000) -> list[int]:
    operand_stack = []
    store = {}
    call_stack = []
    pc = 0
    steps = 0

    while pc < len(program):
        steps += 1
        if steps > max_steps:
            raise StepLimitExceeded()

        instruction = program[pc]
        op = instruction[0]

        if op == "PUSH":
            operand_stack.append(instruction[1])
            pc += 1

        elif op == "POP":
            if len(operand_stack) < 1:
                raise StackUnderflow()
            operand_stack.pop()
            pc += 1

        elif op == "DUP":
            if len(operand_stack) < 1:
                raise StackUnderflow()
            operand_stack.append(operand_stack[-1])
            pc += 1

        elif op == "SWAP":
            if len(operand_stack) < 2:
                raise StackUnderflow()
            operand_stack[-1], operand_stack[-2] = operand_stack[-2], operand_stack[-1]
            pc += 1

        elif op == "ADD":
            if len(operand_stack) < 2:
                raise StackUnderflow()
            b = operand_stack.pop()
            a = operand_stack.pop()
            operand_stack.append(a + b)
            pc += 1

        elif op == "SUB":
            if len(operand_stack) < 2:
                raise StackUnderflow()
            b = operand_stack.pop()
            a = operand_stack.pop()
            operand_stack.append(a - b)
            pc += 1

        elif op == "MUL":
            if len(operand_stack) < 2:
                raise StackUnderflow()
            b = operand_stack.pop()
            a = operand_stack.pop()
            operand_stack.append(a * b)
            pc += 1

        elif op == "DIV":
            if len(operand_stack) < 2:
                raise StackUnderflow()
            b = operand_stack.pop()
            a = operand_stack.pop()
            if b == 0:
                raise VMZeroDivision()
            operand_stack.append(a // b)
            pc += 1

        elif op == "MOD":
            if len(operand_stack) < 2:
                raise StackUnderflow()
            b = operand_stack.pop()
            a = operand_stack.pop()
            if b == 0:
                raise VMZeroDivision()
            operand_stack.append(a % b)
            pc += 1

        elif op == "NEG":
            if len(operand_stack) < 1:
                raise StackUnderflow()
            operand_stack.append(-operand_stack.pop())
            pc += 1

        elif op == "EQ":
            if len(operand_stack) < 2:
                raise StackUnderflow()
            b = operand_stack.pop()
            a = operand_stack.pop()
            operand_stack.append(1 if a == b else 0)
            pc += 1

        elif op == "LT":
            if len(operand_stack) < 2:
                raise StackUnderflow()
            b = operand_stack.pop()
            a = operand_stack.pop()
            operand_stack.append(1 if a < b else 0)
            pc += 1

        elif op == "GT":
            if len(operand_stack) < 2:
                raise StackUnderflow()
            b = operand_stack.pop()
            a = operand_stack.pop()
            operand_stack.append(1 if a > b else 0)
            pc += 1

        elif op == "LOAD":
            operand_stack.append(store.get(instruction[1], 0))
            pc += 1

        elif op == "STORE":
            if len(operand_stack) < 1:
                raise StackUnderflow()
            store[instruction[1]] = operand_stack.pop()
            pc += 1

        elif op == "JMP":
            target = instruction[1]
            if target < 0 or target > len(program):
                raise BadJump()
            pc = target

        elif op == "JZ":
            if len(operand_stack) < 1:
                raise StackUnderflow()
            a = operand_stack.pop()
            if a == 0:
                target = instruction[1]
                if target < 0 or target > len(program):
                    raise BadJump()
                pc = target
            else:
                pc += 1

        elif op == "CALL":
            target = instruction[1]
            if target < 0 or target > len(program):
                raise BadJump()
            call_stack.append(pc + 1)
            pc = target

        elif op == "RET":
            if len(call_stack) < 1:
                raise StackUnderflow()
            pc = call_stack.pop()

        elif op == "HALT":
            return operand_stack

        else:
            raise BadOpcode()

    return operand_stack

haiku-low.template_render:
def render(template: str, values: dict) -> str:
    """
    Render a template with placeholder substitution.

    Placeholders are {name} where name matches [A-Za-z_][A-Za-z0-9_]*.
    {{ renders as {, }} renders as }.
    """
    # First pass: validate template and collect placeholder names
    placeholders = set()
    i = 0

    while i < len(template):
        c = template[i]

        if c == '{':
            if i + 1 < len(template) and template[i + 1] == '{':
                # Escape: {{
                i += 2
            else:
                # Potential placeholder
                j = i + 1
                if j < len(template) and (template[j].isalpha() or template[j] == '_'):
                    # Read identifier
                    ident_start = j
                    while j < len(template) and (template[j].isalnum() or template[j] == '_'):
                        j += 1

                    if j < len(template) and template[j] == '}':
                        # Valid placeholder
                        name = template[ident_start:j]
                        placeholders.add(name)
                        i = j + 1
                    else:
                        # Unclosed placeholder
                        raise ValueError(f"Invalid placeholder at position {i}")
                else:
                    # Invalid placeholder start
                    raise ValueError(f"Invalid placeholder at position {i}")

        elif c == '}':
            if i + 1 < len(template) and template[i + 1] == '}':
                # Escape: }}
                i += 2
            else:
                # Unmatched }
                raise ValueError(f"Unmatched '}}' at position {i}")

        else:
            i += 1

    # Check for missing keys
    missing_keys = placeholders - set(values.keys())
    if missing_keys:
        sorted_missing = sorted(missing_keys)
        raise KeyError("missing keys: " + ", ".join(sorted_missing))

    # Second pass: render
    result = []
    i = 0

    while i < len(template):
        c = template[i]

        if c == '{':
            if i + 1 < len(template) and template[i + 1] == '{':
                # Escape: {{
                result.append('{')
                i += 2
            else:
                # Placeholder
                j = i + 1
                ident_start = j
                while j < len(template) and (template[j].isalnum() or template[j] == '_'):
                    j += 1

                name = template[ident_start:j]
                result.append(str(values[name]))
                i = j + 1

        elif c == '}':
            if i + 1 < len(template) and template[i + 1] == '}':
                # Escape: }}
                result.append('}')
                i += 2
            else:
                # This should not happen if first pass succeeded
                raise ValueError(f"Unmatched '}}' at position {i}")

        else:
            result.append(c)
            i += 1

    return ''.join(result)

haiku-low.text_table:
def format_table(rows: list[list], headers: list[str], *,
                 aligns: list[str] | None = None,
                 max_col_width: int = 20) -> str:
    # Validation
    if not headers:
        raise ValueError("headers cannot be empty")

    if max_col_width < 1:
        raise ValueError("max_col_width must be >= 1")

    for row in rows:
        if len(row) != len(headers):
            raise ValueError("row length mismatch")

    if aligns is None:
        aligns = ["l"] * len(headers)
    elif len(aligns) != len(headers):
        raise ValueError("aligns length mismatch")

    for align in aligns:
        if align not in ("l", "r", "c"):
            raise ValueError("invalid alignment")

    num_cols = len(headers)

    # Split cells by newlines
    header_cell_lines = [h.split('\n') for h in headers]
    data_cell_lines = []
    for row in rows:
        row_cell_lines = []
        for cell in row:
            cell_str = "" if cell is None else str(cell)
            row_cell_lines.append(cell_str.split('\n'))
        data_cell_lines.append(row_cell_lines)

    # Calculate column widths
    col_widths = []
    for col_idx in range(num_cols):
        max_width = 0
        for line in header_cell_lines[col_idx]:
            max_width = max(max_width, len(line))
        for row_cell_lines in data_cell_lines:
            for line in row_cell_lines[col_idx]:
                max_width = max(max_width, len(line))
        col_widths.append(min(max_width, max_col_width))

    # Helper to hard-wrap and align a single line
    def wrap_and_align(line, col_width, align):
        chunks = []
        for i in range(0, len(line), col_width):
            chunks.append(line[i:i+col_width])
        if not chunks:
            chunks = [""]

        aligned = []
        for chunk in chunks:
            if align == "l":
                aligned.append(chunk.ljust(col_width))
            elif align == "r":
                aligned.append(chunk.rjust(col_width))
            else:  # "c"
                left_pad = (col_width - len(chunk)) // 2
                right_pad = col_width - len(chunk) - left_pad
                aligned.append(" " * left_pad + chunk + " " * right_pad)
        return aligned

    # Wrap header cells
    header_wrapped = []
    max_header_height = 0
    for col_idx in range(num_cols):
        col_wrapped = []
        for line in header_cell_lines[col_idx]:
            col_wrapped.extend(wrap_and_align(line, col_widths[col_idx], aligns[col_idx]))
        header_wrapped.append(col_wrapped)
        max_header_height = max(max_header_height, len(col_wrapped))

    # Pad header columns
    for col_idx in range(num_cols):
        while len(header_wrapped[col_idx]) < max_header_height:
            header_wrapped[col_idx].append(" " * col_widths[col_idx])

    # Wrap data cells
    data_wrapped = []
    for row_cell_lines in data_cell_lines:
        row_wrapped = []
        max_row_height = 0
        for col_idx in range(num_cols):
            col_wrapped = []
            for line in row_cell_lines[col_idx]:
                col_wrapped.extend(wrap_and_align(line, col_widths[col_idx], aligns[col_idx]))
            row_wrapped.append(col_wrapped)
            max_row_height = max(max_row_height, len(col_wrapped))

        # Pad columns in this row
        for col_idx in range(num_cols):
            while len(row_wrapped[col_idx]) < max_row_height:
                row_wrapped[col_idx].append(" " * col_widths[col_idx])

        data_wrapped.append(row_wrapped)

    # Build output
    result = []

    # Border
    border = "+" + "+".join("-" * (w + 2) for w in col_widths) + "+"
    result.append(border)

    # Header rows
    for line_idx in range(max_header_height):
        cells = [" " + header_wrapped[col_idx][line_idx] + " " for col_idx in range(num_cols)]
        result.append("|" + "|".join(cells) + "|")

    # Header separator
    result.append(border)

    # Data rows
    for row_wrapped_cols in data_wrapped:
        for line_idx in range(len(row_wrapped_cols[0])):
            cells = [" " + row_wrapped_cols[col_idx][line_idx] + " " for col_idx in range(num_cols)]
            result.append("|" + "|".join(cells) + "|")

    # Bottom border
    result.append(border)

    return "\n".join(result)

haiku-low.wrap_text:
def wrap_text(text: str, width: int) -> str:
    if width < 1:
        raise ValueError("width must be at least 1")

    # Split into paragraphs by blank lines
    paragraphs = []
    current_para = []

    for line in text.split('\n'):
        if line.strip():  # non-blank line
            current_para.append(line)
        else:  # blank line
            if current_para:
                paragraphs.append(current_para)
                current_para = []

    # Don't forget the last paragraph if it exists
    if current_para:
        paragraphs.append(current_para)

    # Process each paragraph
    wrapped_paragraphs = []

    for para_lines in paragraphs:
        # Join lines in the paragraph and split into words
        para_text = ' '.join(para_lines)
        words = para_text.split()

        # Wrap words
        wrapped_lines = []
        current_line = ""

        for word in words:
            # Check if word fits on current line
            if not current_line:
                # Starting a new line
                if len(word) <= width:
                    current_line = word
                else:
                    # Word is too long, hard-break it
                    while len(word) > width:
                        wrapped_lines.append(word[:width])
                        word = word[width:]
                    current_line = word
            else:
                # Current line has content
                if len(current_line) + 1 + len(word) <= width:
                    # Word fits
                    current_line += " " + word
                else:
                    # Word doesn't fit
                    wrapped_lines.append(current_line)

                    # Handle overlong word
                    if len(word) <= width:
                        current_line = word
                    else:
                        # Word is too long, hard-break it
                        while len(word) > width:
                            wrapped_lines.append(word[:width])
                            word = word[width:]
                        current_line = word

        # Add the last line of the paragraph
        if current_line:
            wrapped_lines.append(current_line)

        if wrapped_lines:
            wrapped_paragraphs.append('\n'.join(wrapped_lines))

    # Join paragraphs with empty lines between them
    result = '\n\n'.join(wrapped_paragraphs)

    return result
